  const positional = [];
  const flags = {};
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--help" || a === "-h") return fail("");
    if (a === "--pr" || a === "--previous" || a === "--split") {
      if (i + 1 >= argv.length) return fail(`${a} needs a value`);
      flags[a.slice(2)] = argv[++i];
    } else if (a.startsWith("--")) {
      return fail(`unknown option ${a}`);
    } else {
      positional.push(a);
    }
  }
  if (positional.length !== 3) return fail("give the analysis, the base checkout and the head checkout");
  const [file, base, head] = positional;
  const changedFiles = flags.pr ? JSON.parse(readJson(flags.pr, "pr.json")).files.map((f) => f.path) : null;

try {
  main(process.argv.slice(2));
} catch (e) {
  process.stderr.write(`validate.mjs: ${e.message}\n`);
  process.exitCode = 2;
}

  let out;
  if (flags.split) {
    out = JSON.parse(check_split(readJson(file, "the skeleton"), readJson(flags.split, "split.json"), JSON.stringify(changedFiles)));
  } else {
    const options = {};
    if (changedFiles) options.changedFiles = changedFiles;
    if (flags.previous) {
      const ids = tryRead(join(flags.previous, "previous-ids.json"));
      const vocabulary = tryRead(join(flags.previous, "vocabulary.json"));
      if (ids === undefined && vocabulary === undefined) options.previous = null;
      else if (ids === undefined || vocabulary === undefined)
        return fail(`${flags.previous} holds only one of previous-ids.json and vocabulary.json`);
      else options.previous = { ids: JSON.parse(ids), vocabulary: JSON.parse(vocabulary) };
    }
    out = JSON.parse(validate(readJson(file, "the analysis"), JSON.stringify(options), checkouts({ base, head })));
  }
  const { errors, warnings } = out.report;
  process.stdout.write(`${JSON.stringify(out.report, null, 2)}\n`);
  const counts = out.counts
    ? ` (${Object.entries(out.counts).map(([k, n]) => `${n} ${k}`).join(", ")})`
    : "";
  process.stderr.write(`${errors.length} errors, ${warnings.length} warnings${counts}\n`);
  // Never process.exit(): it can cut a piped report short. Node exits once stdout has drained.
  process.exitCode = errors.length ? 1 : 0;
}

function checkouts(roots) {
  const at = (side, path) => {
    const root = roots[side];
    const full = join(root, path);
    const rel = relative(root, full);
    if (rel.startsWith("..") || isAbsolute(rel)) return undefined;
    return full;
  };
  return {
    read(side, path) {
      const p = at(side, path);
      try {
        return p === undefined ? undefined : readFileSync(p, "utf8");
      } catch {
        return undefined;
      }
    },
    kind(side, path) {
      const p = at(side, path);
      try {
        return p === undefined ? undefined : statSync(p).isDirectory() ? "dir" : "file";
      } catch {
        return undefined;
      }
    },

tracked(side) {
  try {
    // Git's own variables would point it at another repo than the checkout's.
    const env = { ...process.env };
    for (const k of ["GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_COMMON_DIR"]) delete env[k];
    const out = execFileSync("git", ["-C", roots[side], "ls-files", "-z"], {
      encoding: "utf8",
      env,
      maxBuffer: 1 << 30,
      stdio: ["ignore", "pipe", "ignore"],
    });
    const files = out.split("\0").filter((f) => f !== "");
    // None tracked: the folder isn't a checkout of its own (it may sit untracked inside
    // another repo), so there's no count rather than a count of 0.
    return files.length === 0 ? undefined : JSON.stringify(files);
  } catch {
    return undefined;
  }
},

function main(argv) {
  if (argv.includes("--help") || argv.includes("-h")) return fail("");
  let finishing = false;
  let splitFile;
  const files = [];
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--finish") finishing = true;
    else if (a === "--split") {
      if (i + 1 >= argv.length) return fail("--split needs a value");
      splitFile = argv[++i];
    } else if (a.startsWith("--")) return fail(`unknown option ${a}`);
    else files.push(a);
  }
  if (finishing && splitFile !== undefined) return fail("--split goes with the merge, not --finish");
  if (finishing ? files.length !== 1 : files.length === 0) return fail(finishing ? "give one merged file" : "give the fragments");

const out = JSON.parse(finishing ? finish(texts[0]) : merge(JSON.stringify(texts), split));
if (out.analysis !== null) process.stdout.write(`${JSON.stringify(out.analysis, null, 2)}\n`);
const { errors, warnings } = out.report;
process.stderr.write(`${JSON.stringify(out.report, null, 2)}\n`);
const hints = out.analysis?.hints?.length ?? 0;
process.stderr.write(`${errors.length} errors, ${warnings.length} warnings, ${hints} hints left for the seam pass\n`);
// Never process.exit(): it can cut piped output short. Node exits once stdout has drained.
process.exitCode = errors.length ? 1 : 0;

try {
  main(process.argv.slice(2));
} catch (e) {
  process.stderr.write(`merge.mjs: ${e.message}\n`);
  process.exitCode = 2;
}

pub fn record(db: &Path, run: &str) -> Result<Recorded, String> {
    let conn = analysis_db::snapshot(db).map_err(|e| format!("{}: {e}", db.display()))?;
    let an = analysis_db::q::recorded_analysis(&conn, run)
        .map_err(|e| e.to_string())?
        .ok_or_else(|| {
            format!("no accepted analysis of run {run} in {} that's still its PR's (none was accepted, or a later run's replaced it)", db.display())
        })?;
    let row = analysis_db::q::run(&conn, &an.run_id)
        .map_err(|e| e.to_string())?
        .ok_or_else(|| format!("analysis {} names run {}, which is gone", an.id, an.run_id))?;

    let repo = format!("{}/{}", row.owner, row.name);
    if !repo.eq_ignore_ascii_case(RECORDED_REPO) {
        return Err(format!(
            "run {} is on {repo}#{}: only a run on {RECORDED_REPO} is recorded (fixtures/pr-view/ holds beghu's own PR)",
            an.run_id, row.number
        ));
    }
    let pr = row
        .pinned
        .ok_or_else(|| format!("run {} never pinned its PR", an.run_id))?;
    let gz = an.upload_gz.ok_or_else(|| {
        format!("analysis {} was stored before beghu kept upload bodies: record it again from a new run", an.id)
    })?;
    let mut text = String::new();
    flate2::read::MultiGzDecoder::new(&gz[..])
        .read_to_string(&mut text)
        .map_err(|e| format!("the stored upload doesn't inflate: {e}"))?;
    Ok(Recorded {
        pr,
        analysis: text,
        head_sha: an.head_sha,
        number: row.number,
    })
}

/// `fixtures/pr-view/`.
pub fn dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/pr-view")
}

/// The recorded PR's folder (`beghu-<n>`), and the versions recorded in it (1, then 2).
pub fn recordings() -> Vec<(u32, Vec<u32>)> {
    let mut out = Vec::new();
    for e in std::fs::read_dir(dir()).into_iter().flatten().flatten() {
        let name = e.file_name().to_string_lossy().into_owned();
        let Some(n) = name.strip_prefix("beghu-").and_then(|n| n.parse().ok()) else {
            continue;
        };
        let versions = (1..=2)
            .filter(|v| e.path().join(format!("analysis-v{v}.json")).exists())
            .collect();
        out.push((n, versions));
    }
    out.sort();
    out
}

pub fn committed() -> Vec<Committed> {
    let mut out = Vec::new();
    let mut v1_pr = None;
    for (n, versions) in recordings() {
        for v in versions {
            let folder = dir().join(format!("beghu-{n}"));
            let pr = folder.join(format!("pr-v{v}.json"));
            if v == 1 {
                v1_pr.get_or_insert(pr.clone());
            }
            out.push(Committed {
                name: format!("beghu-{n}/analysis-v{v}.json"),
                analysis: folder.join(format!("analysis-v{v}.json")),
                pr,
                previous: (v == 2).then(|| folder.join("analysis-v1.json")),
            });
        }
    }

let mut cases: Vec<PathBuf> = std::fs::read_dir(dir().join("cases"))
    .into_iter()
    .flatten()
    .flatten()
    .map(|e| e.path())
    .filter(|p| p.extension().is_some_and(|x| x == "json"))
    .collect();
cases.sort();
for c in cases {
    let pr: PathBuf = v1_pr.clone().expect("cases are of the recorded PR at v1");
    let name = format!("cases/{}", c.file_name().unwrap().to_string_lossy());
    let previous = name
        .ends_with(&format!("{AFTER_V1}.json"))
        .then(|| pr.with_file_name("analysis-v1.json"));
    out.push(Committed {
        name,
        analysis: c,
        pr,
        previous,
    });
}
out

impl Committed {
    /// What this analysis's `carried` is checked against, as the server checks a later upload:
    /// the IDs and vocabulary of the one it follows, migrated, or none for a first analysis.
    pub fn previous_ids(&self) -> Result<Previous, String> {
        let Some(path) = &self.previous else {
            return Ok(Previous::None);
        };
        let ctx = Context {
            changed_files: None,
            previous: Previous::Unknown,
        };
        let a = analysis::validate(&read(path), &ctx, None)
            .analysis
            .ok_or_else(|| format!("{} doesn't pass the shape check", path.display()))?;
        Ok(Previous::Some {
            ids: PreviousIds::of(&a),
            vocabulary: Vocabulary::of(&a),
        })
    }

impl Committed {
    pub fn analysis_text(&self) -> String {
        read(&self.analysis)
    }

    pub fn pinned(&self) -> PinnedPr {
        serde_json::from_str(&read(&self.pr))
            .unwrap_or_else(|e| panic!("{}: {e}", self.pr.display()))
    }
}

fn read(p: &Path) -> String {
