fn shas() -> Result<(), String> {
    let mut seen = std::collections::BTreeSet::new();
    for c in committed() {
        let v: serde_json::Value =
            serde_json::from_str(&c.analysis_text()).map_err(|e| format!("{}: {e}", c.name))?;
        for k in ["baseSha", "headSha"] {
            if let Some(sha) = v["pr"][k].as_str()
                && seen.insert(sha.to_owned())
            {
                println!("{sha}");
            }
        }
    }
    Ok(())
}

fn migrated(c: &Committed) -> Analysis {
    let pinned = c.pinned();
    let ctx = Context {
        changed_files: Some(pinned.files.iter().map(|f| f.path.clone()).collect()),
        previous: c.previous_ids().unwrap(),
    };
    let out = validate(&c.analysis_text(), &ctx, None);
    assert!(
        out.report.errors.is_empty(),
        "{}: {:#?}",
        c.name,
        out.report.errors
    );
    out.analysis.unwrap()
}

